const TRUST_LEVEL_RANK: Record<string, number> = {
  T0: 0,
  T1: 1,
  T2: 2,
  T3: 3,
  T4: 4,
};

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;

  return `{${Object.keys(value as Record<string, unknown>)
    .sort()
    .map(
      (key) =>
        `${JSON.stringify(key)}:${stableStringify((value as Record<string, unknown>)[key])}`,
    )
    .join(",")}}`;
}

function sha256(value: string) {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

function jsonObject(value: Record<string, unknown>): Prisma.InputJsonObject {
  return value as Prisma.InputJsonObject;
}

function iso(value: Date | string | null | undefined) {
  return value ? new Date(value).toISOString() : null;
}

function decimalNumber(
  value: Prisma.Decimal | number | string | null | undefined,
) {
  if (value === null || value === undefined) return null;
  if (typeof value === "number") return value;
  return Number(value);
}

function metadataRecord(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value as Record<string, unknown>;
}

function stringOrNull(value: unknown) {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function booleanOrNull(value: unknown) {
  return typeof value === "boolean" ? value : null;
}

function numberOrNull(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function stringArray(value: unknown) {
  return Array.isArray(value)
    ? value
        .filter((entry): entry is string => typeof entry === "string")
        .map((entry) => entry.trim())
        .filter(Boolean)
    : [];
}

function redactClosePackEvidenceRef(value?: string | null) {
  if (!value) return null;
  return `redacted:${createHash("sha256").update(value).digest("hex").slice(0, 12)}`;
}

function sensitiveMetadataKey(key: string) {
  const compact = key.toLowerCase().replace(/[^a-z0-9]/g, "");
  return (
    compact.includes("secret") ||
    compact.includes("token") ||
    compact.includes("password") ||
    compact.includes("credential") ||
    compact.includes("apikey") ||
    compact.includes("authorization") ||
    compact === "auth" ||
    compact === "authheader" ||
    compact === "payload" ||
    compact.includes("providerpayload") ||
    compact.includes("rawpayload") ||
    compact.includes("rawprovider") ||
    compact.includes("authoritypayload") ||
    compact.includes("auditpayload") ||
    compact.includes("salaryamount") ||
    compact.includes("personlevelamounts") ||
    compact.includes("employeeid") ||
    compact.includes("paymentdestination")
  );
}

function redactedMetadataValue(value: unknown) {
  if (value === null || value === undefined) return null;
  if (typeof value === "string" && value.trim()) {
    return redactClosePackEvidenceRef(value);
  }
  if (Array.isArray(value)) return value.length ? "redacted" : [];
  if (typeof value === "object") return "redacted";
  return "redacted";
}

function redactSensitiveMetadata(
  value: unknown,
  parentKey = "",
  depth = 0,
): unknown {
  if (sensitiveMetadataKey(parentKey)) return redactedMetadataValue(value);
  if (value === null || value === undefined) return value;
  if (depth > 8) return "redacted";
  if (Array.isArray(value)) {
    return value.map((entry) =>
      redactSensitiveMetadata(entry, parentKey, depth + 1),
    );
  }
  if (typeof value !== "object") return value;

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
      key,
      redactSensitiveMetadata(entry, key, depth + 1),
    ]),
  );
}

function closePackTrustLevelFromMetadata(value: unknown) {
  const trustLevel = stringOrNull(metadataRecord(value).trustLevel);
  return trustLevel && TRUST_LEVEL_RANK[trustLevel] !== undefined
    ? trustLevel
    : null;
}

function closePackTrustRank(value: unknown) {
  const trustLevel = closePackTrustLevelFromMetadata(value);
  return trustLevel ? TRUST_LEVEL_RANK[trustLevel] ?? -1 : -1;
}

function auditPayloadAfter(row: PilotAuditRow | null) {
  const changes = metadataRecord(row?.changes);
  const after = metadataRecord(changes.after);
  return Object.keys(after).length > 0 ? after : changes;
}

function dateOrNull(value: Date | string | null | undefined) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function sourceMetadataForInput(
  input: CloseCertificationInvalidationInput,
): CloseCertificationInvalidationSourceMetadata {
  if (input.sourceCode && input.sourceCode !== "CUSTOM")
    return CLOSE_CERTIFICATION_INVALIDATION_SOURCES[input.sourceCode];

  const matchedSource = Object.values(
    CLOSE_CERTIFICATION_INVALIDATION_SOURCES,
  ).find(
    (source) =>
      source.sourceModel === input.sourceModel &&
      source.sourceEventName === input.sourceEventName,
  );
  if (matchedSource) return matchedSource;

  return {
    sourceCode: input.sourceCode ?? "CUSTOM",
    ring: "CUSTOM",
    domain: "custom",
    sourceModel: input.sourceModel,
    sourceTable: null,
    sourceEventName: input.sourceEventName,
    closeImpact: "CERTIFIED_CLOSE_EVIDENCE_STALE",
  };
}

function sourcePayload(source: CloseCertificationInvalidationSourceMetadata) {
  return {
    sourceCode: source.sourceCode,
    ring: source.ring,
    domain: source.domain,
    sourceModel: source.sourceModel,
    sourceTable: source.sourceTable,
    sourceEventName: source.sourceEventName,
    closeImpact: source.closeImpact,
  };
}

function stringField(value: Record<string, unknown> | null, key: string) {
  const raw = value?.[key];
  return typeof raw === "string" && raw.trim() ? raw : null;
}

function statutoryCertificationBlockerMetadata() {
