    expect(mockDb.ledgerAuditEvent.create).toHaveBeenCalledWith(
      expect.objectContaining({
        data: expect.objectContaining({
          action: "CLOSE_PACK_DRAFT_EXPORT",
          resourceType: "ClosePackExport",
